  assert.match(series.stdout, /S0001/);

  // 再重放：身份（含例外集合）仍在，返回现状而不复活
  const r = importOk(df, f, ['R0001'], '本地改动后重放');
  assert.match(r.stdout, /B0001 \[已取消\]/);
  assert.match(r.stdout, /B0002 \[已预约\][\s\S]*当前安排: 2026-10-13T16:00 → 2026-10-13T17:00/);
});

