  );
  c = crossCheck(df, 'exp-cancel@x', p);
  assert.deepEqual(c, {active: 0, excluded: 4, exceptions: 0});
  assertReport(r, c, '全部取消');
  assert.match(r.stdout, /无有效发生/);
});

