function chmodReadonly(p: string): void {
  const {chmodSync} = require('node:fs') as typeof import('node:fs');
  chmodSync(p, 0o555);
}
function chmodWritable(p: string): void {
  const {chmodSync} = require('node:fs') as typeof import('node:fs');
  chmodSync(p, 0o755);
}

