  mkdirSync(outDir);
  const outPath = join(outDir, 'out.ics');
  writeFileSync(outPath, 'ORIGINAL-CONTENT', 'utf8');
  chmodSync(outDir, 0o555);
  try {
    const r = bizFail(df, ['export-ical', 'exp-keep@x', '--output', outPath], '目录只读导致临时文件写入失败');
