function foldIcalLine(line) {
  const pieces = [];
  let cur = "", curBytes = 0, limit = 75;
  for (const ch of line) {
    const n = Buffer.byteLength(ch, "utf8");
    if (curBytes + n > limit) { pieces.push(cur); cur = ""; curBytes = 0; limit = 74; }
    cur += ch; curBytes += n;
  }
  pieces.push(cur);
  const physical = [pieces[0], ...pieces.slice(1).map(x => " " + x)];
  return physical;
}
